import {$,remainingSeconds,readStore,writeStore,escapeHTML as esc,download} from './core.js';
let history=readStore('swa-focus-history-v1',[]);if(!Array.isArray(history))history=[];let remaining=25*60,total=remaining,deadline=0,running=false,started=false,sessionTitle='';
$('#app').innerHTML=`<div class="grid two"><div class="panel timer"><label>Session intention<input id="task" placeholder="What will you focus on?" maxlength="100"></label><div class="toolbar"><label>Minutes<input id="minutes" type="number" min="1" max="180" value="25"></label></div><div class="dial" id="dial"><div class="dial-inner"><span class="eyebrow" id="mode">READY TO FOCUS</span><span class="clock" id="clock">25:00</span></div></div><div class="toolbar" style="justify-content:center"><button id="start">Start session</button><button id="reset" class="secondary">Reset</button></div><p class="small">You can pause and resume. Closing or reloading this page ends the active session.</p></div><div class="panel"><div class="row"><h2>Completed sessions</h2><span class="badge" id="total"></span></div><div id="history"></div><div class="toolbar"><button id="export" class="secondary">Export history ↓</button><button id="clear" class="secondary">Clear history</button></div></div></div>`;
function renderHistory(){$('#total').textContent=history.length+' sessions';$('#history').innerHTML=history.length?history.slice().reverse().slice(0,12).map(s=>`<div class="session"><strong>${esc(s.title)}</strong><div class="small">${s.minutes} min · ${new Date(s.at).toLocaleDateString()}</div></div>`).join(''):'<p class="empty">Finish your first session to start your record.</p>'}
function draw(){$('#clock').textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;$('#dial').style.setProperty('--progress',(1-remaining/total)*100+'%');$('#start').textContent=running?'Pause':started?'Resume':'Start session';$('#mode').textContent=running?'IN THE ZONE':started?'PAUSED':'READY TO FOCUS';$('#minutes').disabled=started;$('#task').disabled=started}
function complete(){running=false;remaining=0;history.push({title:sessionTitle||'Focused work',minutes:total/60,at:new Date().toISOString()});writeStore('swa-focus-history-v1',history);started=false;renderHistory();draw();$('#mode').textContent='SESSION COMPLETE';$('#status').textContent='Session complete. Take a break — you earned it.'}
$('#start').onclick=()=>{if(running){remaining=remainingSeconds(deadline);if(remaining===0){complete();return}running=false}else{if(!started){const mins=Number($('#minutes').value);if(!Number.isInteger(mins)||mins<1||mins>180){$('#status').textContent='Choose a whole number from 1 to 180 minutes.';return}total=remaining=mins*60;sessionTitle=$('#task').value.trim();started=true}deadline=Date.now()+remaining*1000;running=true;$('#status').textContent='Session started. Keep this page open.'}draw()};$('#reset').onclick=()=>{running=started=false;total=remaining=Math.max(1,Math.min(180,Number($('#minutes').value)||25))*60;draw();$('#status').textContent='Timer reset. Incomplete sessions are not saved.'};$('#minutes').onchange=()=>{if(!started){remaining=total=Math.max(1,Math.min(180,Number($('#minutes').value)||25))*60;draw()}};setInterval(()=>{if(!running)return;remaining=remainingSeconds(deadline);if(remaining===0)complete();else draw()},250);$('#export').onclick=()=>download('focus-sessions.json',JSON.stringify(history,null,2),'application/json');$('#clear').onclick=()=>{if(confirm('Delete your completed session history?')){history=[];writeStore('swa-focus-history-v1',history);renderHistory()}};renderHistory();draw();
